-- MariaDB 11.4; source snapshot from supplied company_dump.sql. Run in one session.
USE `mytemr_master`;
SET NAMES utf8mb4;
SET SESSION sql_mode = 'STRICT_ALL_TABLES,NO_ENGINE_SUBSTITUTION';
SET @cleanup_time = NOW();
CREATE TEMPORARY TABLE `cleanup_dump` (
  `id` int(11) NOT NULL,
  `duplicate_id` varchar(100) NOT NULL,
  `account_id` varchar(250) DEFAULT NULL,
  `name` varchar(100) NOT NULL DEFAULT '',
  `description` text DEFAULT NULL,
  `address` text DEFAULT NULL,
  `street` varchar(255) DEFAULT NULL,
  `telephone` varchar(100) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `tin_no` varchar(250) DEFAULT NULL,
  `mailing_address` varchar(250) DEFAULT NULL,
  `website` text DEFAULT NULL,
  `point_of_contact_name` varchar(255) DEFAULT NULL,
  `designation` varchar(100) DEFAULT NULL,
  `contact_email` varchar(100) DEFAULT NULL,
  `contact_phone` varchar(100) DEFAULT NULL,
  `bank_id` varchar(250) DEFAULT NULL,
  `bank_name` varchar(100) DEFAULT NULL,
  `bank_country` varchar(255) DEFAULT NULL,
  `account_number` varchar(100) DEFAULT NULL,
  `branch` varchar(100) DEFAULT NULL,
  `account_type` varchar(250) DEFAULT NULL,
  `country` text DEFAULT NULL,
  `swift_bic_code` varchar(100) DEFAULT NULL,
  `additional_info` text DEFAULT NULL,
  `province` varchar(255) DEFAULT NULL,
  `city_municipality` varchar(255) DEFAULT NULL,
  `barangay` varchar(255) DEFAULT NULL,
  `business_type` varchar(255) DEFAULT NULL,
  `industry` varchar(255) DEFAULT NULL,
  `estimated_employees` varchar(255) DEFAULT NULL,
  `account_credit_limit` varchar(255) DEFAULT NULL,
  `company_no` varchar(255) DEFAULT NULL,
  `registered_date` date DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `for_releasing_name` varchar(250) DEFAULT NULL,
  `for_releasing_designation` varchar(250) DEFAULT NULL,
  `for_releasing_email` varchar(250) DEFAULT NULL,
  `for_releasing_phone` varchar(250) DEFAULT NULL,
  `autorized_billing_name` varchar(250) DEFAULT NULL,
  `autorized_billing_designation` varchar(250) DEFAULT NULL,
  `autorized_billing_email` varchar(250) DEFAULT NULL,
  `autorized_billing_phone` varchar(250) DEFAULT NULL,
  `type` enum('hmo','company','insurance','government','corporate','school') NOT NULL DEFAULT 'company',
  `classification` varchar(255) DEFAULT NULL,
  `industry_category` varchar(255) DEFAULT NULL,
  `region` varchar(255) DEFAULT NULL,
  `account_status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `accreditation_status` enum('pending','approved','hold','active','inactive') NOT NULL DEFAULT 'pending',
  `account_terms` varchar(255) DEFAULT NULL,
  `consumable_amount_per_employee` decimal(13,2) NOT NULL DEFAULT 0.00,
  `discount_amount` decimal(13,2) NOT NULL DEFAULT 0.00,
  `discount_percentage` varchar(250) DEFAULT NULL,
  `wallet_validity_date_from` date DEFAULT NULL,
  `wallet_validity_date_to` date DEFAULT NULL,
  `is_hmo` int(11) NOT NULL DEFAULT 0,
  `added_by` int(11) NOT NULL,
  `added_on` datetime NOT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `updated_on` datetime DEFAULT NULL,
  `is_deleted` tinyint(4) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TEMPORARY TABLE cleanup_company_map (old_id INT PRIMARY KEY, final_id INT NOT NULL) ENGINE=InnoDB;
CREATE TEMPORARY TABLE cleanup_company_projection ENGINE=InnoDB AS SELECT c.id, COALESCE(d.name,c.name) name, CASE WHEN d.id IS NOT NULL THEN CAST(NULLIF(TRIM(d.account_id),'') AS SIGNED) ELSE c.account_id END account_id, CASE WHEN d.id IS NOT NULL THEN 0 WHEN m.old_id IS NOT NULL THEN 1 ELSE c.is_deleted END deleted FROM company c LEFT JOIN cleanup_dump d ON d.id=c.id LEFT JOIN cleanup_company_map m ON m.old_id=c.id;
CREATE TEMPORARY TABLE cleanup_collision_keys ENGINE=InnoDB AS SELECT name,account_id,deleted FROM cleanup_company_projection WHERE account_id IS NOT NULL GROUP BY name,account_id,deleted HAVING COUNT(*)>1;
CREATE TEMPORARY TABLE cleanup_name_changes (id INT PRIMARY KEY,old_name VARCHAR(100),new_name VARCHAR(100)) ENGINE=InnoDB;
UPDATE cleanup_company_projection p JOIN cleanup_name_changes n ON n.id=p.id SET p.name=n.new_name;
