INSERT INTO cleanup_name_changes SELECT p.id,p.name,CONCAT(LEFT(p.name,100-CHAR_LENGTH(CONCAT(' [merged #',p.id,']'))), ' [merged #',p.id,']') FROM cleanup_company_projection p JOIN cleanup_collision_keys k ON p.name=k.name AND p.account_id=k.account_id AND p.deleted=k.deleted JOIN cleanup_company_map m ON m.old_id=p.id;
